                    audit.record("LATE_ENTRY sheet=" + sheet + " by=" + by + " person=" + person.name()
                            + " amount=" + added.amount().toPlainString() + " date=" + added.date());
                }
                made++;
            }
        }
        rollup.record(sheet, by, before);
        result.set(new GenerateResult(made));
    }
}
